function concertoWeapon(id, name, weaponType, tier = 3) {
  return refinements((r, rank) => {
    const CEASELESS_ARIA = new Buff({
      name: `${name}: Ceaseless Aria${rank} (ready)`,
      updateBuffs: () => {
        if (!casting(
          3
          /* Cast.Skill */
        ))
          return;
        addGain({ concerto: [800, 1e3, 1200, 1400, 1600][r] });
        revokeCurrent(CEASELESS_ARIA);
      }
    });
    return new Weapon({
      id,
      weaponType,
      tier,
      name: `${name}${rank}`,
      stats: [[0, 337.5], [11, 51.84]],
      combatStart: () => applyCurrent(CEASELESS_ARIA, 1),
      grants: [{ on: onCast(
        6
        /* Cast.Outro */
      ), buff: CEASELESS_ARIA }]
    });
  });
}
