var RUNES = new Buff({
  name: "Sigrika: Runes",
  maxStacks: 511,
  display: () => {
    const word = frozenStacks();
    let slots = "";
    for (let k = 0; k < 4; k++)
      slots += "-TAF"[word >> 2 * k & 3];
    return `Sigrika: Runes [${slots}]`;
  }
});
function fullStops(word) {
  let n = 0;
  while (n < 4 && (word >> 2 * n & 3) === 3)
    n++;
  return n;
}
function gainRune(kind, by) {
  const doubler = by === "Convergent" ? CONVERGENT : by === "Divergent" ? DIVERGENT : null;
  let extra = 0;
  if (doubler && isHeld(doubler)) {
    extra = doubler === CONVERGENT ? kind : 3 - kind;
    revokeCurrent(doubler);
  } else if (doubler)
    addGain({ forte1: -1 });
  if (!pushRune(kind))
    addGain({ forte1: -1 });
  if (extra && !pushRune(extra))
    addGain({ forte1: -1 });
}
function pushRune(kind) {
  const word = stacksOf(RUNES), at = 2 * fullStops(word);
  if (at >= 8)
    return false;
  const a = word >> at & 3, b = word >> at + 2 & 3;
  const pair = !a ? kind : !b ? a | kind << 2 : b | kind << 2;
  setRunes(word & ~(15 << at) | pair << at);
  return !a || !b;
}
