    name: `Rime-Draped Sprouts: Panorama${rank} (skill)`,
    maxStacks: 3,
    duration: 60 * 6,
    stats: [[
      18,
      [12, 15, 18, 21, 24][r],
      4096
      /* Type.Basic */
    ]],
