function aemeathAction(id, def2) {
  const { lays, ...rest } = def2;
  if (lays && rest.bullets)
    rest.bullets = laidBehind(rest.bullets, lays);
  return new Action(id, { element: 192, scaling: 0, ...rest });
}
var event = (frame, fn, commitFrame = frame) => ({ hitFrame: frame, commitFrame, element: null, type: null, subtype: null, updateDebuffs: fn });
var laidBehind = (bullets, lay) => bullets.flatMap((b) => [b, event(b.hitFrame + 5, lay, b.commitFrame ?? b.hitFrame)]).sort((a, b) => a.hitFrame - b.hitFrame);
