function mistEarned() {
  const me = currentTeam().slot;
  return consumedAny() > 0 || stacksOfTeam(MOUNTAINS_WASHED) > 0 && (inflictedNegativeStatusBy(me) || NEGATIVE_STATUS_TAGS.some(isType));
}
